<style>
  .logo {
    display: block;
    overflow: visible;
  }

  .mark {
    /* Пульс вокруг центра самой фигуры, а не точки (0,0) */
    transform-box: fill-box;
    transform-origin: center;
    /* Два независимых ритма: быстрое «дыхание» + медленное покачивание */
    animation:
      breathe 2.4s cubic-bezier(0.4, 0, 0.2, 1) infinite,
      sway 6s ease-in-out infinite;
    will-change: transform, opacity;
  }

  /* Дыхание: 0% и 100% совпадают → петля без рывка */
  @keyframes breathe {
    0%,
    100% {
      transform: scale(0.9);
      opacity: 0.55;
    }
    50% {
      transform: scale(1.04);
      opacity: 1;
    }
  }

  /* Едва заметное покачивание — «живой», не механический пульс */
  @keyframes sway {
    0%,
    100% {
      rotate: -2deg;
    }
    50% {
      rotate: 2deg;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .mark {
      animation: none;
      opacity: 1;
      transform: none;
      rotate: none;
    }
  }
</style>